#!/usr/bin/env node
/**
 * Register a new package across every surface that lists packages.
 *
 *   node scripts/add-package.mjs --id dsh-foo --name-zh "示例插件" \
 *     --name-en "Foo example" --positioning "One sentence." \
 *     --category business-ops --subcategory finance --archetype ingest \
 *     --task-family 财务报销 --roles 会计 --industries 财务 --tags 标签1,标签2
 *
 * Writes: taxonomy.v1.json, data/zh-meta.json, README.md (one table row), and a
 * card in docs/index.html. Family views, the market index/page and the docs are
 * regenerated by their own builders afterwards.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')

const argv = process.argv.slice(2)
const arg = (name, fallback = '') => {
  const i = argv.indexOf(`--${name}`)
  return i >= 0 ? argv[i + 1] : fallback
}

const id = arg('id')
if (!id) throw new Error('--id is required')
const nameZh = arg('name-zh')
const nameEn = arg('name-en', id)
const positioning = arg('positioning', '')
const category = arg('category', 'business-ops')
const subcategory = arg('subcategory', 'general')
const archetype = arg('archetype', 'ingest')
const taskFamily = arg('task-family', '行政办公')
const roles = arg('roles').split(',').filter(Boolean)
const industries = arg('industries').split(',').filter(Boolean)
const tags = arg('tags').split(',').filter(Boolean)

// 1. taxonomy
const taxPath = path.join(root, 'taxonomy.v1.json')
const tax = JSON.parse(fs.readFileSync(taxPath, 'utf8'))
if (tax.items.some((x) => x.id === id)) {
  console.log(`${id} already in taxonomy`)
} else {
  tax.items.push({
    id,
    kind: 'plugin',
    collection: 'domain-ops',
    category,
    subcategory,
    archetype,
    checker: false,
    checkerRole: 'none',
    domains: tags.length ? tags : [subcategory],
    displayName: nameEn,
    displayNameZh: nameZh,
    positioning,
    status: 'active',
    release: 'alpha',
    version: '0.1.0-alpha.1',
    relatedCheckers: [],
  })
  fs.writeFileSync(taxPath, JSON.stringify(tax, null, 2) + '\n')
  console.log(`taxonomy: added ${id} (${tax.items.length} items)`)
}

// 2. Chinese metadata
const zhPath = path.join(root, 'data', 'zh-meta.json')
const zh = JSON.parse(fs.readFileSync(zhPath, 'utf8'))
zh[id] = { nameZh, tags, taskFamily, roles, industries }
fs.writeFileSync(zhPath, JSON.stringify(zh, null, 2) + '\n')
console.log(`zh-meta: ${id} -> ${nameZh}`)

// 3. README table row
const readmePath = path.join(root, 'README.md')
let readme = fs.readFileSync(readmePath, 'utf8')
if (!readme.includes(`](https://github.com/PerryLink/${id})`)) {
  const anchor = readme.split('\n').findIndex((l) => l.startsWith('| [`dsh-provider-params`]'))
  const row = `| [\`${id}\`](https://github.com/PerryLink/${id}) | ${nameZh}：${positioning} | \`0.1.0-alpha.1\` | \`dsh plugin --profile <profile> add ${id}\` |`
  if (anchor < 0) throw new Error('README anchor row not found; add the row by hand')
  const lines = readme.split('\n')
  lines.splice(anchor + 1, 0, row)
  readme = lines.join('\n')
  fs.writeFileSync(readmePath, readme)
  console.log('README: row added')
}

// 4. docs/index.html card
const indexPath = path.join(root, 'docs', 'index.html')
let index = fs.readFileSync(indexPath, 'utf8')
if (!index.includes(`packages/${id}.html`)) {
  const card = `<article class="card"><h3><a href="packages/${id}.html">${id}</a></h3><p>${nameZh}：${positioning}</p><p class="meta"><code>0.1.0-alpha.1</code> · <a href="https://www.npmjs.com/package/${id}">npm</a> · <a href="https://github.com/PerryLink/${id}">GitHub</a></p></article>`
  const anchorCard = index.indexOf('</div><h2>一键安装 suite</h2>')
  if (anchorCard < 0) throw new Error('index anchor not found; add the card by hand')
  index = index.slice(0, anchorCard) + card + index.slice(anchorCard)
  fs.writeFileSync(indexPath, index)
  console.log('docs/index.html: card added')
}

console.log('done — now run: sync-versions, build-family, build-docs, build-market-index, build-market-page')
